// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.

public enum CandidateAction: Equatable, Hashable {

    case removeKnownRegenerableContents
    case evictLocalCopy
    case moveToTrash
    case revealOnly
    case noAction





}

